from django.db import migrations, models
from django.db.models import Count


def drop_duplicate_cards(apps, schema_editor):
    """Keep one row per Stripe card: the default if a copy is one, else the newest.

    The copies are the same card cached twice by racing webhooks, so only the
    stale copy is lost.
    """
    PaymentMethod = apps.get_model("organizations", "PaymentMethod")
    duplicated = (
        PaymentMethod.objects.exclude(stripe_id="")
        .values("stripe_id")
        .annotate(n=Count("pk"))
        .filter(n__gt=1)
        .values_list("stripe_id", flat=True)
    )
    for stripe_id in list(duplicated):
        rows = PaymentMethod.objects.filter(stripe_id=stripe_id)
        keep = rows.order_by("-is_default", "-pk").first()
        rows.exclude(pk=keep.pk).delete()


